package ru.neverland.townydistricts.service;
import java.util.*;
import ru.neverland.townydistricts.model.*;
public final class PatrolLayoutSmoke {
    static int checks;static void check(boolean yes,String why){if(!yes)throw new AssertionError(why);checks++;}interface Work{void run()throws Exception;}static void reject(Work work)throws Exception{try{work.run();}catch(Exception expected){checks++;return;}throw new AssertionError("not immutable");}
    @SuppressWarnings("unchecked")public static void main(String[]args)throws Exception{UUID town=UUID.randomUUID(),world=UUID.randomUUID();var cells=Set.of(new Cell(world,-1,0),new Cell(world,0,0));var district=new District(town,"port","Порт",DistrictType.RESIDENTIAL,cells);var layout=DistrictService.createPatrolLayout(town,List.of(district),cells,16,1000);var cache=Map.of(town,layout);check(Boolean.TRUE.equals(layout.get("available")),"owned physical district captured");var rows=(List<Map<String,Object>>)layout.get("rows");check(rows.get(0).get("world").equals(world.toString())&&((List<?>)rows.get(0).get("cells")).size()==2,"negative coordinate physical geometry preserved");reject(()->rows.clear());reject(()->((List<Map<String,Object>>)rows.get(0).get("cells")).get(0).put("x",8));check(DistrictService.checkedPatrolLayout(town,cache,1000,false,16000,16)==layout,"fresh snapshot returned by identity with no reconstruction");check(Boolean.FALSE.equals(DistrictService.checkedPatrolLayout(town,cache,1000,false,16001,16).get("available")),"older than fifteen seconds unavailable");check(Boolean.TRUE.equals(DistrictService.checkedPatrolLayout(town,cache,1000,true,1001,16).get("pending")),"claim dirty is pending instead of old geometry");check(Boolean.FALSE.equals(DistrictService.checkedPatrolLayout(town,Map.of(),0,false,1001,16).get("available")),"failed refresh cannot expose old geometry");check(Boolean.FALSE.equals(DistrictService.checkedPatrolLayout(town,cache,1000,false,999,16).get("available")),"clock rollback not silently fresh");check(Boolean.FALSE.equals(DistrictService.createPatrolLayout(town,List.of(district),Set.of(new Cell(world,0,0)),16,1000).get("available")),"lost or unloaded ownership never accepted");check(Boolean.FALSE.equals(DistrictService.createPatrolLayout(UUID.randomUUID(),List.of(district),cells,16,1000).get("available")),"foreign town rejected");check(Boolean.FALSE.equals(DistrictService.checkedPatrolLayout(UUID.randomUUID(),cache,1000,false,1001,16).get("available")),"uncaptured town unknown not empty success");System.out.println("PatrolLayoutSmoke PASS "+checks+" checks");}
}
